                            }
                        },
                        Exec(_) | Default => {
                            let deghosted_orig = remove_ghost_from_exec_fn(&f_orig);
                            let deghosted_changed = remove_ghost_from_exec_fn(&f_changed);
                            // after deghost, check exact match.
